Import ListNotations.
Open Scope Z_scope.
Set Warnings "-notation-for-abbreviation".
Local Ltac Z.euclidean_division_equations_cleanup ::= idtac.
Local Ltac acc_hint ::= bdtA_acc_hint.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Section CANSEC1. Context {rc : runConstT}.

Section F1A.
  Variables (SP SPA : Z) (gp tp : word) (F : bvmap 5 word) (fc : bv 32) (RNG : footprint).
  Variables (x1 x18 x19 x21 x22 x23 x24 x25 x26 x29 x30 x31 : word) (len : Z).
  Variables (m0 : amem) (DT SY cnt sym0 u0 nb : Z) (syms : list (option Z)) (js jt : list byte) (ncells : nat).
  Variables (w u sym cnt' SY' : Z) (j144 j160 j192 j208 : list byte).
  Variable Q : machine_state -> Prop.
  Hypothesis HJT : length jt = (2 * ncells)%nat.
  Hypothesis HJS : length js = length syms.
  Hypothesis HSYR : forall i v, nth i syms None = Some v -> 0 <= v < 256.
  Hypothesis HNB : 0 <= nb < 256.
  Hypothesis HDT : ablk (DT + 4) (DT + 4 + 2 * Z.of_nat ncells).
  Hypothesis HSY : ablk SY (SY + zlen js).
  Hypothesis DJ : DT + 4 + 2 * Z.of_nat ncells <= SY \/ SY + zlen js <= DT + 4.
  Hypothesis DSP : DT + 4 + 2 * Z.of_nat ncells <= SPA.
  Hypothesis SYSP : SY + zlen js <= SPA.
  Hypothesis SP47 : SPA + 312 <= 2^47.
  Hypothesis UDT : unpoisoned m0 (DT + 4) (DT + 4 + 2 * Z.of_nat ncells).
  Hypothesis ZSY : zshadow m0 SY (zlen js).
  Hypothesis AWD : appW [(DT + 4, DT + 4 + 2 * Z.of_nat ncells); (SPA + 136, SPA + 296)].
  Hypothesis RDT : rng RNG (DT + 4) (2 * Z.of_nat ncells).
  Hypothesis RDTs : rng RNG (shad DT) (nshad (4 + 2 * Z.of_nat ncells + DT mod 8)).
  Hypothesis RSY : rng RNG SY (zlen js).
  Hypothesis RSYs : rng RNG (shad SY) (nshad (zlen js + SY mod 8)).

  Notation INV m1 cells := (x1fA_inv m0 m1 SPA DT SY js jt syms ncells cells).
  Notation FRC := (x1frA w u sym cnt' SY' j144 j160 j192 j208).
  Notation LS pc mm x5 x6 x7 x11 x12 x13 x17 x28 :=
    (MS (mkR x1 (Z_to_bv 64 SPA) gp tp x5 x6 x7 (Z_to_bv 64 SP) (Z_to_bv 64 SPA) (Z_to_bv 64 nb) x11 x12 x13
             (Z_to_bv 64 (2 * cnt)) (Z_to_bv 64 (DT + 2 * u0)) (Z_to_bv 64 (DT + 4 + 2 * u0)) x17 x18 x19
             (Z_to_bv 64 2147450880) x21 x22 x23 x24 x25 x26 (Z_to_bv 64 len) x28 x29 x30 x31)
        F (Z_to_bv 64 pc) fc None mm (seg_rom asegs)).

  Lemma f1A_inner : forall f s cells m1 r (x5 x6 x7 x12 x28 : word),
    fill_syms f s cnt sym0 1 nb syms cells (u0 + s) = Ok r ->
    Z.of_nat f = cnt - s + 1 -> 0 <= s < cnt -> 0 <= u0 -> 0 <= sym0 -> INV m1 cells -> rw_cells asegs m1 (SPA + 136) FRC ->
    (forall m2 cells' (y5 y6 y7 y11 y12 y13 y17 y28 : word),
       r = (cells', u0 + cnt) -> INV m2 cells' -> rw_cells asegs m2 (SPA + 136) FRC ->
       evtF asegs RNG Q (LS 0x80a1c m2 y5 y6 y7 y11 y12 y13 y17 y28)) ->
